#include <string.h>
#include <stdlib.h>

// Function to retrieve a floorplan image based on a request and send it back in the reply
void send_floorplan_image(WebEmSession* session, const request* req, reply* rep) {
    // Extract the "idx" parameter from the request
    const char* idx = request_get_param(req, "idx");
    if (!idx || idx[0] == '\0') {
        // If "idx" is empty or null, exit early
        return;
    }

    // Query the database for the image associated with the given ID
    unsigned char* image_data = NULL;
    size_t image_size = 0;
    int success = database_query_image(idx, &image_data, &image_size);

    if (!success || !image_data || image_size == 0) {
        // If no image is found, exit
        return;
    }

    // Determine the file extension based on the first byte of the image data
    const char* file_extension = "unknown";
    if (image_size > 0) {
        switch (image_data[0]) {
            case 'P': // PNG
                file_extension = "png";
                break;
            case 'G': // GIF
                file_extension = "gif";
                break;
            case '\377': // JPEG
                file_extension = "jpg";
                break;
            default:
                file_extension = "unknown";
                break;
        }
    }

    // Set the content of the reply with the image data
    reply_set_content(rep, image_data, image_size);

    // Add the file extension as an attachment header to the reply
    char filename[256];
    snprintf(filename, sizeof(filename), "floorplan.%s", file_extension);
    reply_add_header(rep, "Content-Disposition", filename);

    // Free the allocated memory for the image data
    free(image_data);
}
